B.Gv=new A.bm("Funeral","Voc\xea tem uma vis\xe3o de um caix\xe3o aberto e est\xe1 deitado nele.",null,"Sanidade",null,B.JX,null,"Se as pe\xe7as Cemit\xe9rio ou Catacumbas tiverem sido descobertas, coloque seu explorador em uma dessas pe\xe7as.")
B.GE=new A.bm("Elevador Secreto","Uma parede se abre para revelar um elevador de pratos. \xc9 apertado, mas voc\xea poderia rastejar para dentro se precisasse.",null,null,null,B.O,"Voc\xea pode se posicionar em qualquer pe\xe7a em uma regi\xe3o diferente.",null)
B.Er=new A.a8("3-4","Ganhe 1 ponto de Conhecimento.",'"...essa m\xfasica foi lan\xe7ada!" Uma melodia alegre come\xe7a a tocar.')
B.Fk=new A.a8("0-2","Receba um dado de dano mental.",'"... um ataque nuclear foi lan\xe7ado sobre Washington, D.C."')
B.JI=s([B.Er,B.Fk],t.W)
B.H_=new A.bm("Transmiss\xe3o de R\xe1dio",'Um r\xe1dio chiando atr\xe1s de voc\xea e uma voz distorcida come\xe7a a ler not\xedcias de anos atr\xe1s. "Neste dia, em 1980..."',null,null,"Jogue 2 dados.",B.JI,null,null)
B.EG=new A.a8("4+","Compre uma carta de Item.","Deve ter sido um efeito da luz. O que \xe9 aquilo no ch\xe3o?")
