B.GH=new A.bm("Um Grito por Socorro",'A voz de um homem ecoa pelos corredores, chamando voc\xea pelo nome. Ela grita em agonia: "Ajude-me!"',null,"Conhecimento",null,B.KX,null,null)
B.F_=new A.a8("4+","Ganhe 1 ponto de Sanidade.",'"Ch\xe1 e bolinhos, ch\xe1 e bolinhos. Voc\xea sempre foi meu favorito."')
B.DV=new A.a8("3","Ganhe 1 ponto de Conhecimento.",'"Estou sempre aqui para voc\xea. Observando."')
